import puppeteer from 'puppeteer-core';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const types = {
  '.html': 'text/html', '.js': 'text/javascript', '.md': 'text/plain', '.json': 'application/json',
};
const files = {
  '/index.html': 'index.html',
  '/main.js': 'main.js',
};

const server = http.createServer((req, res) => {
  const url = req.url.split('?')[0];
  const f = files[url];
  if (!f) { res.writeHead(404); res.end('nope'); return; }
  const body = fs.readFileSync(path.join(root, f));
  res.writeHead(200, { 'Content-Type': types[path.extname(f)] });
  res.end(body);
});
await new Promise(r => server.listen(0, r));
const port = server.address().port;

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: 'new',
  args: [
    '--no-sandbox', '--disable-dev-shm-usage',
    '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
    '--window-size=900,600', '--hide-scrollbars',
  ],
});
const page = await browser.newPage();
await page.setViewport({ width: 900, height: 600 });
const errors = [];
page.on('console', m => {
  const t = m.text();
  if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${t}`);
});
page.on('pageerror', e => errors.push(`[pageerror] ${e.message}`));
page.on('requestfailed', r => errors.push(`[requestfailed] ${r.url()} ${r.failure()?.errorText}`));

await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: 'load', timeout: 60000 });
await new Promise(r => setTimeout(r, 6000));

const info = await page.evaluate(() => {
  const c = document.querySelector('canvas');
  const gl = c && (c.getContext('webgl2') || c.getContext('webgl'));
  return {
    hasCanvas: !!c,
    size: c ? [c.width, c.height] : null,
    renderer: gl ? gl.getParameter(gl.getExtension('WEBGL_debug_renderer_info')?.UNMASKED_RENDERER_WEBGL ?? gl.RENDERER) : null,
  };
});

await page.screenshot({ path: '/tmp/surf1.png' });
await new Promise(r => setTimeout(r, 3500));
await page.screenshot({ path: '/tmp/surf2.png' });
await page.screenshot({ path: '/tmp/surf3.png', clip: { x: 300, y: 150, width: 300, height: 300 } });

// sample the framebuffer to be sure something bright/dark is actually drawn
const stats = await page.evaluate(() => {
  const c = document.querySelector('canvas');
  const gl = c.getContext('webgl2') || c.getContext('webgl');
  const w = 200, h = 140;
  const px = new Uint8Array(w * h * 4);
  gl.readPixels((c.width - w) / 2 | 0, (c.height - h) / 2 | 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px);
  let sum = 0, min = 255, max = 0;
  for (let i = 0; i < px.length; i += 4) {
    const l = (px[i] + px[i + 1] + px[i + 2]) / 3;
    sum += l; min = Math.min(min, l); max = Math.max(max, l);
  }
  return { mean: sum / (w * h), min, max };
});

console.log('canvas info:', JSON.stringify(info));
console.log('framebuffer stats:', JSON.stringify(stats));
console.log('console/page messages:', errors.length ? '\n' + errors.join('\n') : '(none)');

await browser.close();
server.close();

