import puppeteer from 'puppeteer-core';
import http from 'node:http';
import fs from 'node:fs';
import { execFileSync } from 'node:child_process';

const root = process.cwd();

// bundle exactly the way the packaging step will
execFileSync('esbuild', ['main.js', '--bundle', '--format=esm', '--outfile=__bundle.js'], { cwd: root });
const bundle = fs.readFileSync(root + '/__bundle.js');
const html = fs.readFileSync(root + '/index.html', 'utf8')
  .replace('./main.js', './__bundle.js');

const routes = {
  '/': html,
  '/__bundle.js': bundle,
};

const server = http.createServer((req, res) => {
  const url = req.url.split('?')[0];
  const body = routes[url];
  if (body === undefined) { res.writeHead(404); res.end('nope'); return; }
  res.writeHead(200, {
    'Content-Type': url.endsWith('.js') ? 'text/javascript' : 'text/html',
  });
  res.end(body);
});
await new Promise(r => server.listen(0, r));
const port = server.address().port;

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: 'new',
  args: [
    '--no-sandbox', '--disable-dev-shm-usage',
    '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
    '--window-size=960,600', '--hide-scrollbars', '--mute-audio',
  ],
});
const page = await browser.newPage();
await page.setViewport({ width: 960, height: 600 });
const errors = [];
page.on('console', m => {
  if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`);
});
page.on('pageerror', e => errors.push(`[pageerror] ${e.message}`));
page.on('requestfailed', r => errors.push(`[requestfailed] ${r.url()} ${r.failure()?.errorText}`));

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'load', timeout: 60000 });
await new Promise(r => setTimeout(r, 5000));

const info = await page.evaluate(() => {
  const c = document.querySelector('canvas');
  if (!c) return { hasCanvas: false };
  const gl = c.getContext('webgl2') || c.getContext('webgl');
  const dbg = gl.getExtension('WEBGL_debug_renderer_info');
  return {
    hasCanvas: true,
    size: [c.width, c.height],
    renderer: dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : 'unknown',
  };
});
console.log('CANVAS:', JSON.stringify(info));

// sample the framebuffer: is anything actually drawn, and is it varied?
const stats = await page.evaluate(() => {
  const c = document.querySelector('canvas');
  const gl = c.getContext('webgl2') || c.getContext('webgl');
  const w = 240, h = 160;
  const px = new Uint8Array(w * h * 4);
  gl.readPixels((c.width - w) / 2 | 0, (c.height - h) / 2 | 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px);
  let sum = 0, min = 255, max = 0, black = 0;
  for (let i = 0; i < px.length; i += 4) {
    const l = (px[i] + px[i + 1] + px[i + 2]) / 3;
    sum += l; min = Math.min(min, l); max = Math.max(max, l);
    if (l < 4) black++;
  }
  return { mean: +(sum / (w * h)).toFixed(1), min, max, blackPct: +(100 * black / (w * h)).toFixed(2) };
});
console.log('FRAMEBUFFER:', JSON.stringify(stats));

await page.screenshot({ path: root + '/__shot1.png' });
await new Promise(r => setTimeout(r, 4000));
await page.screenshot({ path: root + '/__shot2.png' });
await page.mouse.move(480, 300); // prove nothing is interactive (should not throw)
await new Promise(r => setTimeout(r, 1500));
await page.screenshot({ path: root + '/__shot3.png' });

console.log('MESSAGES:', errors.length ? '\n' + errors.join('\n') : '(none)');

await browser.close();
server.close();

